/** `expiresInDays` is a whole number of days from the moment the invite is sent. */
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Pending means not accepted, not revoked, and not yet expired. Only those
 * rows hold a seat; expiry and revocation free the seat immediately.
 */
function pendingPredicate(orgId: OrgId): SQL | undefined {
  return and(
    orgPredicate(invitations.orgId, orgId),
    isNull(invitations.acceptedAt),
    isNull(invitations.revokedAt),
    gt(invitations.expiresAt, toIsoTimestamp(new Date())),
  );
}

export async function insertInvitation(
  orgId: OrgId,
  input: CreateInvitationInput,
  invitedBy: UserId,
  tokenHash: string,
): Promise<Invitation> {
  const stamp = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + input.expiresInDays * MS_PER_DAY),
  );

  const row = getDb()
    .insert(invitations)
    .values({
      id: newId(),
      orgId,
      email: input.email.trim().toLowerCase(),
      role: input.role,
      invitedBy,
      tokenHash,
      expiresAt,
      acceptedAt: null,
      revokedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toInvitation(row);
}

