): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        pendingPredicate(orgId),
        sql`lower(${invitations.email}) = ${email.trim().toLowerCase()}`,
      ),
    )
    .get();
  return row ? toInvitation(row) : null;
}

