export async function setActiveOrg(
  sessionId: SessionId,
  orgId: OrgId | null,
): Promise<void> {
  getDb()
    .update(sessions)
    .set({ activeOrgId: orgId, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(sessions.id, sessionId))
    .run();
}

/** Sessions whose default workspace is `orgId`, optionally for one user. */
export async function listSessionsForActiveOrg(
  orgId: OrgId,
  userId: UserId | null,
): Promise<readonly { id: SessionId; userId: UserId }[]> {
  const rows = getDb()
    .select({ id: sessions.id, userId: sessions.userId })
    .from(sessions)
    .where(
      userId === null
        ? eq(sessions.activeOrgId, orgId)
        : and(eq(sessions.activeOrgId, orgId), eq(sessions.userId, userId)),
    )
    .all();

  return rows.map((row) => ({
    id: brandId<SessionId>(row.id),
    userId: brandId<UserId>(row.userId),
  }));
}

