  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (!org || org.archivedAt !== null) {
    throw new Error("That workspace has been deleted");
  }

  const user = await userRepo.findUserById(userId);
  if (
    !user ||
    normalizeEmail(user.email) !== normalizeEmail(invitation.email)
  ) {
    throw new Error("That invitation was sent to a different email address");
  }

  const prior = await memberRepo.findMemberIncludingArchived(
    invitation.orgId,
    userId,
  );
  const alreadyActive = prior !== null && prior.archivedAt === null;

  if (!alreadyActive) {
    const seatsUsed =
      (await memberRepo.countActiveMembers(invitation.orgId)) +
      (await invitationRepo.countPendingInvitations(invitation.orgId));
    // The pending invite already holds its seat, so accepting it does not
    // add one. Refuse only when the workspace is already over its plan.
    if (wouldExceedLimit(org.plan, "seats", seatsUsed, 0)) {
      const limits = getPlanLimits(org.plan);
      throw new Error(
        `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
      );
    }
  }

  const acceptedAt = toIsoTimestamp(new Date());
  let member: Member;
  let joined = false;

  if (prior && prior.archivedAt !== null) {
    member = await memberRepo.reinstateMember(
      invitation.orgId,
      prior.id,
      invitation.role,
      invitation.invitedBy,
      acceptedAt,
    );
    joined = true;
  } else if (prior) {
    member = prior;
  } else {
    member = await memberRepo.insertMember(
      invitation.orgId,
      userId,
      invitation.role,
      invitation.invitedBy,
    );
    joined = true;
  }

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );

  if (joined) {
    await emit("member.joined", {
      ...envelope(invitation.orgId, userId),
      memberId: member.id,
      userId,
      role: member.role,
    });
  }

  return member;
}

input.old_string:
/**
 * Re-issuing does not mint a new row: the original is revoked and replaced so
 * the audit trail keeps both, and the old link stops working immediately.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo
      .listPendingInvitations(actor.orgId)
      .then((rows) => rows.find((row) => row.id === invitationId) ?? null),
    "Invitation",
    invitationId,
  );

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  // A re-issued link starts at the lowest invitable role; whoever resends it
  // can promote the person once they have joined.
  return inviteMember(actor, {
    orgId: actor.orgId,
    email: previous.email,
    role: "member",
  });
}

input.new_string:
/**
 * Withdraws the old link and issues a new one to the same address with the
 * same role, valid for 14 days from now. An expired invitation can be re-sent;
 * that is the usual reason to re-send one.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );

  if (previous.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (previous.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  return inviteMember(actor, {
    orgId: actor.orgId,
    email: previous.email,
    role: previous.role as InviteMemberInput["role"],
  });
}

