import type { Actor, SessionPrincipal } from "@/types/member";

input.old_string:
export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  return sessionRepo.findSessionByTokenHash(hashToken(token));
}

input.new_string:
export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  const tokenHash = hashToken(token);
  const principal = await sessionRepo.findSessionByTokenHash(tokenHash);
  if (!principal || principal.activeOrgId === null) return principal;

  if (await isUsableDefaultOrg(principal.userId, principal.activeOrgId)) {
    return principal;
  }

  await releaseDefaultOrg(principal.activeOrgId, principal.userId);
  return sessionRepo.findSessionByTokenHash(tokenHash);
}

/**
 * Stops `orgId` being the default workspace. Sessions that already default to
 * some other org are left alone. When the user still belongs to another
 * workspace, that one becomes the default; otherwise the default is cleared.
 * Pass `userId` null to retarget every session that points at the org.
 */
export async function releaseDefaultOrg(
  orgId: OrgId,
  userId: UserId | null,
): Promise<void> {
  const sessions = await sessionRepo.listSessionsForActiveOrg(orgId, userId);

  for (const session of sessions) {
    const orgs = await orgRepo.listOrgsForUser(session.userId);
    const next = orgs.find((org) => org.id !== orgId);
    await sessionRepo.setActiveOrg(session.id, next?.id ?? null);
  }
}

async function isUsableDefaultOrg(
  userId: UserId,
  orgId: OrgId,
): Promise<boolean> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org || org.archivedAt !== null) return false;

  const member = await memberRepo.findMember(orgId, userId);
  return member !== null && member.status === "active";
}

